sp_page.css:
html,
body,
#sp-page-root,
.sp-page-root,
.sp-page,
.sp-row-content,
.main,
main {
    width: 100% !important;
    max-width: none !important;

    min-height: 100vh !important;

    margin: 0 !important;
    padding: 0 !important;

    background: #FBF8EF !important;
}


.container,
.container-fluid {
    width: 100% !important;
    max-width: none !important;

    margin: 0 !important;
    padding: 0 !important;

    background: #FBF8EF !important;
}


.row {
    width: 100% !important;

    margin: 0 !important;
    padding: 0 !important;
}


[class*="col-"] {
    margin: 0 !important;
    padding: 0 !important;
}


body {
    overflow-x: hidden !important;
}
